#!/usr/bin/env python3
# Builds the served homepage from the raw pre-go-live snapshot by injecting:
#   - social/canonical meta (incl. og:image)
#   - a privacy-first, cookieless analytics beacon we control (-> /api/pv -> autonome_pageviews)
#   - a mobile hamburger nav
#   - contact links (mailto + a form modal -> /api/contact -> AgentMail + autonome_contacts)
#   - the "Talk with Max" sandboxed chat widget
# worker.mjs is then generated by embedding this output + og.jpg as base64.
import os

HERE = os.path.dirname(os.path.abspath(__file__))
SRC = os.path.join(HERE, "..", "live-home-2026-07-19.html")  # deploy/live-home-2026-07-19.html
OUT = "/tmp/site_final.html"
html = open(SRC, encoding="utf-8").read()

# ---------- 1. HEAD: social cards, canonical, cookieless first-party analytics ----------
anchor = '<meta property="og:description" content="Autonomous intelligence. Human purpose. Trust that is earned, not simulated.">'
assert anchor in html, "og:description anchor not found"

head_add = anchor + """
<meta property="og:url" content="https://autonome.ricricho.com/">
<meta property="og:site_name" content="Autonome">
<meta property="og:image" content="https://autonome.ricricho.com/og.jpg">
<meta property="og:image:width" content="1200">
<meta property="og:image:height" content="630">
<meta property="og:image:alt" content="Autonome — an artificial person that grows up.">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:title" content="Autonome — an artificial person that grows up">
<meta name="twitter:description" content="Autonomous intelligence. Human purpose. Trust that is earned, not simulated.">
<meta name="twitter:image" content="https://autonome.ricricho.com/og.jpg">
<link rel="canonical" href="https://autonome.ricricho.com/">
<meta name="theme-color" content="#050506">
<!-- Analytics: first-party, cookieless. Page views + widget events -> /api/pv -> Supabase autonome_pageviews. No cookies, no third party, no banner. -->
<script>
(function(){
  function track(ev){
    try{
      var body=JSON.stringify({event:ev||'pageview',path:location.pathname,referrer:document.referrer||''});
      if(navigator.sendBeacon){navigator.sendBeacon('/api/pv',new Blob([body],{type:'application/json'}));}
      else{fetch('/api/pv',{method:'POST',headers:{'Content-Type':'application/json'},body:body,keepalive:true});}
    }catch(e){}
  }
  window.autonomeTrack=track;
  if(document.readyState!=='loading')track('pageview');
  else document.addEventListener('DOMContentLoaded',function(){track('pageview');});
})();
</script>"""
html = html.replace(anchor, head_add, 1)

# ---------- 2. Mobile nav CSS (replace the display:none rule) ----------
old_rule = "@media(max-width:900px){.navlinks{display:none}}"
assert old_rule in html, "nav media rule not found"
new_rule = """.navactions{display:flex;align-items:center;gap:12px}
  .navtog{display:none}
  .hamb{display:none}
  @media(max-width:900px){
    .hamb{display:inline-flex;flex-direction:column;justify-content:center;gap:5px;width:42px;height:42px;cursor:pointer;border:1px solid var(--line2);border-radius:11px;padding:0 9px}
    .hamb span{display:block;width:20px;height:2px;background:var(--ink);border-radius:2px}
    .navlinks{position:absolute;top:62px;left:0;right:0;display:none;flex-direction:column;gap:0;background:rgba(6,6,8,.97);backdrop-filter:saturate(160%) blur(18px);border-bottom:1px solid var(--line);padding:6px 26px 18px}
    .navtog:checked~.navlinks{display:flex}
    .navlinks a{padding:14px 2px;border-top:1px solid var(--line);font-size:15px}
    .navcta{display:none}
  }"""
html = html.replace(old_rule, new_rule, 1)

# ---------- 3. Nav markup: hamburger + Contact link (opens form modal, mailto fallback) ----------
old_nav = """<nav><div class="wrap">
  <a class="mark" href="#top"><span class="orbmark"></span><span class="wm">Autonome <span>· by Ric Richardson</span></span></a>
  <div class="navlinks">
    <a href="#idea">Overview</a>
    <a href="#faces">The autonomes</a>
    <a href="#how">How it works</a>
    <a href="#battle">Battle of the bots</a>
    <a href="https://github.com/RicRicho/Autonome/blob/main/wiki/Home.md">Wiki</a>
  </div>
  <a class="navcta" href="#faces">Meet an autonome →</a>
</div></nav>"""
assert old_nav in html, "nav block not found"
new_nav = """<nav><div class="wrap">
  <a class="mark" href="#top"><span class="orbmark"></span><span class="wm">Autonome <span>· by Ric Richardson</span></span></a>
  <input type="checkbox" id="navtog" class="navtog" aria-hidden="true">
  <div class="navlinks">
    <a href="#idea">Overview</a>
    <a href="#faces">The autonomes</a>
    <a href="#how">How it works</a>
    <a href="#battle">Battle of the bots</a>
    <a href="https://github.com/RicRicho/Autonome/blob/main/wiki/Home.md">Wiki</a>
    <a href="mailto:max@mail.ricricho.com" onclick="if(window.Contact&&Contact.open){Contact.open();return false;}">Contact</a>
  </div>
  <div class="navactions">
    <a class="navcta" href="#faces">Meet an autonome →</a>
    <label for="navtog" class="hamb" aria-label="Toggle menu"><span></span><span></span><span></span></label>
  </div>
</div></nav>"""
html = html.replace(old_nav, new_nav, 1)

# ---------- 4. Footer: Contact (form modal, mailto fallback) + Talk with Max ----------
old_foot = """  <div class="foothref">
    <a href="https://github.com/RicRicho/Autonome/blob/main/wiki/Home.md">Full wiki</a>
    <a href="https://github.com/RicRicho/Autonome">GitHub</a>
    <a href="#top">Back to top</a>
  </div>"""
assert old_foot in html, "footer href block not found"
new_foot = """  <div class="foothref">
    <a href="https://github.com/RicRicho/Autonome/blob/main/wiki/Home.md">Full wiki</a>
    <a href="https://github.com/RicRicho/Autonome">GitHub</a>
    <a href="mailto:max@mail.ricricho.com" onclick="if(window.Contact&&Contact.open){Contact.open();return false;}">Contact</a>
    <a href="#top" onclick="if(window.Max&&Max.open){Max.open();return false;}">Talk with Max</a>
    <a href="#top">Back to top</a>
  </div>"""
html = html.replace(old_foot, new_foot, 1)

# ---------- 5. Contact form modal (before the chat widget) ----------
contact = """
<!-- ===== Contact form (posts to /api/contact -> AgentMail max@mail.ricricho.com) ===== -->
<style>
  #ctov{position:fixed;inset:0;z-index:70;display:none;align-items:center;justify-content:center;padding:20px;
    background:rgba(3,3,5,.66);backdrop-filter:blur(4px)}
  #ctov.open{display:flex}
  #ctcard{width:min(440px,100%);background:var(--panel);border:1px solid var(--line2);border-radius:18px;
    box-shadow:0 40px 120px rgba(0,0,0,.65);overflow:hidden}
  .ct-head{display:flex;align-items:center;gap:11px;padding:16px 18px;border-bottom:1px solid var(--line);
    background:linear-gradient(180deg,var(--panel2),var(--panel))}
  .ct-head b{flex:1;font-size:15.5px;font-weight:640}
  .ct-head .x{cursor:pointer;color:var(--muted);border:0;background:none;font-size:22px;line-height:1;padding:2px 6px}
  .ct-head .x:hover{color:var(--ink)}
  .ct-body{padding:16px 18px 18px;display:flex;flex-direction:column;gap:11px}
  .ct-body label{font-size:12px;color:var(--faint);margin:0 0 -5px 2px}
  .ct-body input,.ct-body textarea{width:100%;padding:11px 13px;border-radius:11px;border:1px solid var(--line2);
    background:var(--bg2);color:var(--ink);font:inherit;font-size:14px;line-height:1.4;box-sizing:border-box}
  .ct-body textarea{resize:vertical;min-height:104px}
  .ct-body input:focus,.ct-body textarea:focus{outline:none;border-color:var(--accent)}
  .ct-note{color:var(--faint);font-size:11.5px;line-height:1.45;margin:0 2px}
  .ct-send{margin-top:3px;padding:12px 14px;border-radius:12px;border:0;cursor:pointer;background:var(--ink);color:#000;font:inherit;font-size:14.5px;font-weight:600}
  .ct-send:disabled{opacity:.5;cursor:default}
  .ct-ok{color:#9fe7c0;font-size:13.5px}
</style>
<div id="ctov" role="dialog" aria-label="Contact Max" aria-modal="true">
  <div id="ctcard">
    <div class="ct-head"><b>Get in touch</b><button class="x" id="ctx" aria-label="Close">×</button></div>
    <div class="ct-body" id="ctform">
      <label for="ctname">Name</label>
      <input id="ctname" type="text" maxlength="120" placeholder="Your name" autocomplete="name">
      <label for="ctemail">Email</label>
      <input id="ctemail" type="email" maxlength="200" placeholder="you@example.com" autocomplete="email">
      <label for="ctmsg">Message</label>
      <textarea id="ctmsg" maxlength="4000" placeholder="What's on your mind?"></textarea>
      <p class="ct-note">Goes straight to Max at max@mail.ricricho.com. Prefer your own email app? <a href="mailto:max@mail.ricricho.com">Email directly</a>.</p>
      <button class="ct-send" id="ctsend">Send message</button>
    </div>
  </div>
</div>
<script>
(function(){
  var ov=document.getElementById('ctov'),card=document.getElementById('ctcard'),
      x=document.getElementById('ctx'),send=document.getElementById('ctsend'),form=document.getElementById('ctform');
  function open(){ov.classList.add('open');setTimeout(function(){document.getElementById('ctname').focus();},30);}
  function close(){ov.classList.remove('open');}
  window.Contact={open:open,close:close};
  x.onclick=close;
  ov.addEventListener('click',function(e){if(e.target===ov)close();});
  document.addEventListener('keydown',function(e){if(e.key==='Escape')close();});
  send.onclick=function(){
    var name=document.getElementById('ctname').value.trim(),
        email=document.getElementById('ctemail').value.trim(),
        msg=document.getElementById('ctmsg').value.trim();
    if(!msg){document.getElementById('ctmsg').focus();return;}
    send.disabled=true;send.textContent='Sending…';
    fetch('/api/contact',{method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({name:name,email:email,message:msg})})
    .then(function(r){return r.json().then(function(j){return{status:r.status,j:j};});})
    .then(function(res){
      if(res.status===200&&res.j&&res.j.ok){
        form.innerHTML='<p class="ct-ok">Thanks — your message is on its way to Max. We\\'ll be in touch.</p>';
      }else{
        send.disabled=false;send.textContent='Send message';
        var e=(res.j&&res.j.error)||'Something went wrong — try again, or email max@mail.ricricho.com.';
        alert(e);
      }
    })
    .catch(function(){send.disabled=false;send.textContent='Send message';alert('Network hiccup — try again, or email max@mail.ricricho.com.');});
  };
})();
</script>
<!-- ===== end contact form ===== -->
"""

# ---------- 6. Chat widget (before </body>) ----------
widget = open(os.path.join(HERE, "widget.html"), encoding="utf-8").read()
html = html.replace("</body>", contact + widget + "\n</body>", 1)

open(OUT, "w", encoding="utf-8").write(html)
print("wrote", OUT, len(html), "bytes")
